    def WriteStatus(self, command, value, qualifier=None):
        Status = self.Commands[command]['Status']
        if qualifier:
            for Parameter in qualifier:
                if Parameter not in Status:
                    Status[Parameter] = {}
                Status = Status[Parameter]
        try:
            if Status['Live'] != value:
                Status['Changed'] = True
            else:
                Status['Changed'] = False
        except KeyError:
            Status['Changed'] = True
        finally:
            Status['Live'] = value


